37	@SpringBootTest
38	@AutoConfigureMockMvc
39	@ActiveProfiles("test")
40	class EmergencyOverrideApiTest {
41	
42	    private static final String DAY = "2026-09-22";
43	    private static final String GRANT_FROM = "2026-09-22T00:00:00.000+08:00";
44	    private static final String GRANT_TO = "2026-09-23T00:00:00.000+08:00";
45	    private static final String T_10 = "2026-09-22T10:00:00.000+08:00";
46	    private static final String T_11 = "2026-09-22T11:00:00.000+08:00";
