        return jdbc.query("SELECT channel_id, business_day, version FROM playout_mix_draft"
                        + " WHERE channel_id = ? AND business_day = ?",
                DRAFT_MAPPER, channelId, Date.valueOf(businessDay)).stream().findFirst();
    }

